return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=1; plural=0;','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'Pergi ke Carian Pemalam','Activate %s' => 'Aktifkan %s','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s</strong> memerlukan <strong>%2$s</strong> dipasang dan diaktifkan. <a href="%4$s">%3$s</a>','Enter your code here' => 'Masukkan kod anda di sini','Add %s' => 'Tambah %s','Remove' => 'Alih keluar','Order number and receipt will be sent to this email address.' => 'Nombor pesanan dan resit akan dihantar ke alamat e-mel ini.','Apartment, unit, building, floor, etc.' => 'Pangsapuri, unit, bangunan, lantai, dll.','Shipping phone' => 'Telefon penghantaran','Only used for shipping-related questions.' => 'Hanya digunakan untuk soalan berkaitan penghantaran.','Single step' => 'Langkah tunggal','Click to go to the order summary' => 'Klik untuk pergi ke ringkasan pesanan','Cart total:' => 'Jumlah troli:','Proceed to %s' => 'Teruskan ke %s','Proceed to contact' => 'Teruskan menghubungi','Proceed to shipping' => 'Teruskan ke penghantaran','Proceed to billing' => 'Teruskan ke pengebilan','Proceed to payment' => 'Teruskan ke pembayaran','Shipping method' => 'Kaedah penghantaran','Additional notes' => 'Nota tambahan','Payment method' => 'Kaedah pembayaran','Step %1$s of %2$s' => 'Langkah %1$s daripada %2$s','Change: %s' => 'Perubahan: %s','Not selected yet.' => 'Belum terpilih lagi.','Same as shipping address' => 'Sama seperti alamat penghantaran','Same as billing address' => 'Sama seperti alamat pengebilan','Order summary' => 'Ringkasan pesanan','Edit cart' => 'Edit troli','Did you mean %s?' => 'Adakah anda maksudkan %s?','Change email address to: {suggestion-value}' => 'Tukar alamat e-mel kepada: {suggestion-value}','This is a required field.' => 'Ini adalah medan yang diperlukan.','This is not a valid email address.' => 'Ini bukan alamat e-mel yang sah.','This field does not match the related field value.' => 'Medan ini tidak sepadan dengan nilai medan yang berkaitan.','The CPF number "{cpf_number}" is invalid.' => 'Nombor CPF &quot;{cpf_number}&quot; adalah tidak sah.','The CNPJ number "{cnpj_number}" is invalid.' => 'Nombor CNPJ &quot;{cnpj_number}&quot; tidak sah.','(Required)' => '(Diperlukan)','Checkout Header - Desktop' => 'Pengepala Checkout - Desktop','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'Paparkan widget pada pengepala pembayaran untuk skrin besar. Hanya dipaparkan jika menggunakan pengepala daftar keluar pemalam.','Checkout Header - Mobile' => 'Pengepala Checkout - Mudah Alih','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'Paparkan widget di bawah pengepala pembayaran untuk peranti mudah alih. Hanya dipaparkan jika menggunakan pengepala daftar keluar pemalam.','Checkout Sidebar' => 'Bar Sisi Checkout','Display widgets on the checkout sidebar after the order summary.' => 'Paparkan widget pada bar sisi pembayaran selepas ringkasan pesanan.','Checkout Order Summary' => 'Ringkasan Pesanan Checkout','Display widgets inside the order summary at the checkout page.' => 'Paparkan widget di dalam ringkasan pesanan di halaman pembayaran.','Checkout Below Place Order' => 'Checkout Di Bawah Tempat Pesanan','Display widgets below the place order button at the checkout page.' => 'Paparkan widget di bawah butang pesanan tempat di halaman pembayaran.','Checkout Footer' => 'Pengaki Checkout','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'Paparkan widget pada pengaki daftar keluar. Hanya dipaparkan jika menggunakan pengaki daftar keluar pemalam.','Classic' => 'Klasik','Boxed' => 'Berkotak-kotak','Split' => 'Berpisah','Minimalist' => 'Minimalis','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'Pemalam Fluid Checkout dan Tarikh Penghantaran oleh CodeRockz','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>Kami mengesan bahawa anda menggunakan pemalam Masa Tarikh Penghantaran &amp; Pengambilan untuk WooCommerce (percuma dan PRO) oleh CodeRockz. Penyepaduan dengan pemalam ini telah dialihkan ke Fluid Checkout PRO.</p>','Upgrade to PRO' => 'Naik taraf kepada PRO','Fluid Checkout database updated successfully' => 'Pangkalan data Fluid Checkout berjaya dikemas kini','The database changes where applied successfully.' => 'Pangkalan data berubah apabila digunakan dengan jayanya.','Dismiss' => 'Tolak','Fluid Checkout database update' => 'Kemas kini pangkalan data Fluid Checkout','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'Beberapa perubahan pada pangkalan data diperlukan. Seperti mana-mana kemas kini, kami mengesyorkan anda <strong>mengambil sandaran penuh tapak web anda sebelum meneruskan</strong> .','Update database' => 'Kemas kini pangkalan data','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Fluid Checkout tidak serasi dengan susun atur pembayaran Divi Builder','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Fluid Checkout memerlukan borang pembayaran berasaskan kod pendek WooCommerce klasik untuk berfungsi. Apabila menggunakan Divi Builder untuk menyesuaikan rupa dan rasa halaman pembayaran, kod pendek klasik digantikan dengan widget tersuai daripada Divi Builder untuk setiap bahagian halaman pembayaran. Widget tersuai ini tidak serasi dengan Fluid Checkout.</p><p> Sila edit halaman pembayaran anda menggantikan widget Divi Builder dengan widget teks yang mengandungi kod pendek <code>[woocommerce_checkout]</code> .</p>','Edit the checkout page' => 'Edit halaman pembayaran','Read the documentation.' => 'Baca dokumentasi.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'Ciri daftar keluar berbilang langkah PRO Jerman perlu dilumpuhkan apabila menggunakan Fluid Checkout','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Apabila menggunakan Fluid Checkout, ciri berbilang langkah daripada pemalam PRO Germanized menjadi tidak diperlukan dan boleh menyebabkan <strong>ralat kritikal semasa memproses pesanan baharu</strong> . Sila lumpuhkan ciri daftar keluar berbilang langkah PRO Jerman dalam tetapan pemalam.','Go to Germanized settings' => 'Pergi ke tetapan Jerman','Thanks for choosing Fluid Checkout!' => 'Terima kasih kerana memilih Fluid Checkout!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'Anda telah menggunakan pemalam untuk seketika sekarang. Bagaimana anda menyukainya setakat ini?<br> Sila beri kami penilaian pantas, kami menghargai setiap maklum balas dan ia menggalakkan kami untuk terus menambah baik pemalam :)','Rate the plugin' => 'Nilaikan pemalam','I need help!' => 'Saya perlukan bantuan!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Sesetengah ciri Pengurus WooCommerce Checkout oleh Quadlayers mungkin tidak berfungsi seperti yang diharapkan apabila menggunakannya dengan Fluid Checkout. Baca <a href="%s">dokumentasi kami</a> untuk mendapatkan maklumat lanjut dan penyelesaian alternatif.','Read documentation' => 'Baca dokumentasi','Don\'t show this again' => 'Jangan tunjukkan ini lagi','Fluid Checkout PRO' => 'Fluid Checkout PRO','More design templates' => 'Lebih banyak templat reka bentuk','Optimized cart page' => 'Halaman troli yang dioptimumkan','Optimized order received / thank you page' => 'Pesanan yang dioptimumkan diterima / halaman terima kasih','Edit cart contents at checkout page' => 'Edit kandungan troli di halaman pembayaran','Account matching / user matching' => 'Padanan akaun / padanan pengguna','Trust symbols on the cart and thank you pages' => 'Simbol amanah pada troli dan halaman terima kasih','More positions for the coupon code on the checkout page' => 'Lebih banyak kedudukan untuk kod kupon pada halaman pembayaran','International phone numbers' => 'Nombor telefon antarabangsa','Gift messages and packing slips' => 'Mesej hadiah dan slip pembungkusan','Local pickup and in-store collection' => 'Pengambilan tempatan dan koleksi dalam kedai','EU-VAT Assistant' => 'Pembantu EU-VAT','I already have it – Hide this offer' => 'Saya sudah memilikinya – Sembunyikan tawaran ini','Activated' => 'Diaktifkan','Address book' => 'Buku alamat','Select an image' => 'Pilih imej','Cart layout' => 'Susun atur troli','Cart optimizations' => 'Pengoptimuman troli','Enable cart page optimizations' => 'Dayakan pengoptimuman halaman troli','Header and footer template' => 'Templat pengepala dan pengaki','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'Mengawal sama ada untuk menggunakan pengepala dan pengaki halaman bebas gangguan atau mengekalkan pengepala dan pengaki tema yang sedang aktif.','Distraction free header and footer' => 'Pengepala dan pengaki bebas gangguan','Theme\'s header and footer' => 'Pengepala dan pengaki tema','Cart elements' => 'Elemen troli','Make the order summary stay visible on the cart page while scrolling' => 'Jadikan ringkasan pesanan kekal kelihatan pada halaman troli semasa menatal','Coupon codes' => 'Kod kupon','Hidden' => 'Tersembunyi','Before the cart items section' => 'Sebelum bahagian barang troli','Inside the cart items section' => 'Di dalam bahagian barang troli','After the cart items section' => 'Selepas bahagian barang troli','Before the shipping section' => 'Sebelum bahagian penghantaran','After the shipping section' => 'Selepas bahagian penghantaran','Before the order summary' => 'Sebelum ringkasan pesanan','Inside the order summary' => 'Di dalam ringkasan pesanan','Before the order totals' => 'Sebelum jumlah pesanan','After the order totals' => 'Selepas jumlah pesanan','After the order summary' => 'Selepas ringkasan pesanan','Shipping' => 'Penghantaran','Select position where to display the shipping costs and calculator on the cart page.' => 'Pilih kedudukan untuk memaparkan kos penghantaran dan kalkulator pada halaman troli.','Display as a cart section' => 'Paparkan sebagai bahagian troli','Cross-sells' => 'Jualan silang','Select position where to display the cross-sells section on the cart page.' => 'Pilih kedudukan tempat untuk memaparkan bahagian jualan silang pada halaman troli.','Before the cart actions' => 'Sebelum troli bertindak','After the cart actions' => 'Selepas tindakan troli','Layout of cross-sell items on the cart page.' => 'Susun atur item jualan silang pada halaman troli.','Optimized horizontal cross-sells layout' => 'Susun atur jualan silang mendatar yang dioptimumkan','Theme\'s cross-sells layout' => 'Susun atur jualan silang tema','Number of cross-sell items to display on the cart page' => 'Bilangan item jualan silang untuk dipaparkan pada halaman troli','Add widget areas to the cart page' => 'Tambahkan kawasan widget pada halaman troli','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'Kawasan widget ini digunakan untuk menambah simbol amanah dan lencana kepercayaan pada halaman troli.','Checkout' => 'Checkout','Checkout layout' => 'Susun atur pembayaran','Design template' => 'Templat reka bentuk','Dark mode' => 'Mod gelap','Enable dark mode' => 'Dayakan mod gelap','Logo image' => 'Imej logo','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'Pilih imej untuk dipaparkan pada pengepala halaman pembayaran. Hanya terpakai apabila menggunakan pengepala dan pengaki bebas gangguan.','Header background color' => 'Warna latar belakang pengepala','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'Pilih warna latar belakang untuk pengepala halaman pembayaran. Hanya terpakai apabila menggunakan pengepala dan pengaki bebas gangguan.','HTML color value. ie: #f3f3f3' => 'Nilai warna HTML. iaitu: #f3f3f3','Page background color' => 'Warna latar belakang halaman','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'Pilih warna latar belakang untuk halaman pembayaran. Warna digunakan pada elemen <em>badan</em> .','Footer background color' => 'Warna latar belakang pengaki','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'Pilih warna latar belakang untuk pengaki halaman daftar keluar. Hanya terpakai apabila menggunakan pengepala dan pengaki bebas gangguan.','Progress bar' => 'Bar kemajuan','Display the checkout progress bar when using multi-step checkout layout' => 'Paparkan bar kemajuan pembayaran apabila menggunakan reka letak pembayaran berbilang langkah','Make the checkout progress bar stay visible while scrolling' => 'Jadikan bar kemajuan pembayaran kekal kelihatan semasa menatal','Express checkout' => 'Daftar keluar ekspres','Enable the express checkout section' => 'Dayakan bahagian daftar keluar ekspres','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'Memaparkan bahagian daftar keluar ekspres semasa pembayaran apabila get laluan pembayaran yang disokong mendayakan ciri ini.','Display express checkout buttons in one line for larger screens' => 'Paparkan butang daftar keluar ekspres dalam satu baris untuk skrin yang lebih besar','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'Abaikan medan pembayaran tambahan yang diperlukan apabila membayar dengan gerbang pembayaran pembayaran ekspres yang serasi','Make the order summary stay visible while scrolling' => 'Jadikan ringkasan pesanan kekal kelihatan semasa menatal','Choose a background color for the order summary section.' => 'Pilih warna latar belakang untuk bahagian ringkasan pesanan.','Highlight the order totals row in the order summary table' => 'Serlahkan baris jumlah pesanan dalam jadual ringkasan pesanan','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'Paling berguna apabila bahagian ringkasan pesanan tidak mempunyai warna latar belakang yang diserlahkan. Mungkin juga digunakan pada halaman Troli, Pesanan Diterima dan Lihat Pesanan apabila menggunakan Fluid Checkout PRO.','Action link on the order summary at checkout.' => 'Pautan tindakan pada ringkasan pesanan semasa pembayaran.','Edit cart link' => 'Edit pautan troli','Cart items count' => 'Item troli dikira','Link to shop page' => 'Pautan ke halaman kedai','Cart items' => 'Barangan troli','Hide cart items errors at the checkout page' => 'Sembunyikan ralat item troli di halaman pembayaran','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'Jangan paparkan mesej ralat item troli di bahagian atas halaman pembayaran. Apabila menyerahkan borang pembayaran untuk melengkapkan pembelian, mesej ralat ini akan sentiasa dipaparkan.','Place order' => 'Buat pesanan','Define the position to display "Place order" and terms checkbox section.' => 'Tentukan kedudukan untuk memaparkan bahagian kotak semak &quot;Buat pesanan&quot; dan terma.','Some options might not be compatible with some plugins and themes.' => 'Sesetengah pilihan mungkin tidak serasi dengan beberapa pemalam dan tema.','Below the payment section' => 'Di bawah bahagian pembayaran','Below the order summary' => 'Di bawah ringkasan pesanan','Both below the payment section and the order summary' => 'Kedua-duanya di bawah bahagian pembayaran dan ringkasan pesanan','Add widget areas to the checkout page' => 'Tambahkan kawasan widget pada halaman pembayaran','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'Kawasan widget ini digunakan untuk menambah simbol amanah dan lencana kepercayaan pada halaman pembayaran.','Display the coupon codes section title' => 'Paparkan tajuk bahagian kod kupon','Select position where to display the coupon codes section on the checkout page.' => 'Pilih kedudukan untuk memaparkan bahagian kod kupon pada halaman pembayaran.','Before the checkout steps' => 'Sebelum langkah checkout','As a substep before payment methods' => 'Sebagai substep sebelum kaedah pembayaran','As a substep after payment methods' => 'Sebagai substep selepas kaedah pembayaran','Default button style' => 'Gaya butang lalai','"Add" link button' => 'Butang pautan &quot;Tambah&quot;.','Checkout fields' => 'Medan pembayaran','Optional fields' => 'Medan pilihan','Hide optional fields behind a link button' => 'Sembunyikan medan pilihan di belakang butang pautan','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'Adalah disyorkan untuk memastikan pilihan ini disemak untuk mengurangkan bilangan medan input terbuka, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">baca penyelidikan</a> .','Do not hide "Address line 2" fields behind a link button' => 'Jangan sembunyikan medan &quot;Baris alamat 2&quot; di belakang butang pautan','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'Disyorkan hanya apabila kebanyakan pelanggan benar-benar memerlukan medan &quot;Baris alamat 2&quot;, atau apabila mendapatkan alamat penghantaran yang betul adalah penting (iaitu jika menghantar makanan dan produk mudah rosak yang lain).','Billing address' => 'Alamat pengebilan','Select position where to display the billing address section on the checkout page.' => 'Pilih kedudukan untuk memaparkan bahagian alamat pengebilan pada halaman pembayaran.','As a step before shipping' => 'Sebagai langkah sebelum penghantaran','As a sub-step before the shipping address section' => 'Sebagai sub-langkah sebelum bahagian alamat penghantaran','As a sub-step after the shipping address section' => 'Sebagai sub-langkah selepas bahagian alamat penghantaran','As a step after shipping' => 'Sebagai langkah selepas penghantaran','As a sub-step before the payment section' => 'Sebagai sub-langkah sebelum bahagian pembayaran','Force billing and shipping addresses to the same (single section)' => 'Paksa pengebilan dan alamat penghantaran ke yang sama (bahagian tunggal)','Checkbox for "Same as shipping/billing address" checked by default' => 'Kotak pilihan untuk &quot;Sama seperti alamat penghantaran/pengebilan&quot; ditandai secara lalai','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'Kotak semak &quot;Sama seperti alamat penghantaran&quot; akan bermula seperti yang ditandakan secara lalai apabila bahagian alamat penghantaran dipaparkan dahulu.<br> Kotak pilihan &quot;Sama seperti alamat pengebilan&quot; akan bermula seperti yang ditandakan secara lalai apabila bahagian alamat pengebilan dipaparkan dahulu.<br> Adalah disyorkan untuk membiarkan pilihan ini ditandakan untuk mengurangkan dengan ketara bilangan medan input terbuka semasa pembayaran, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">baca penyelidikan</a> .','Highlight the billing address section in the checkout form' => 'Serlahkan bahagian alamat pengebilan dalam borang pembayaran','Shipping address' => 'Alamat penghantaran','Highlight the shipping address section in the checkout form' => 'Serlahkan bahagian alamat penghantaran dalam borang pembayaran','Shipping methods' => 'Kaedah penghantaran','Choose in which position to display the shipping methods section.' => 'Pilih di kedudukan mana untuk memaparkan bahagian kaedah penghantaran.','Before shipping address' => 'Sebelum alamat penghantaran','After shipping address' => 'Selepas alamat penghantaran','Local pickup' => 'Pickup tempatan','Removes shipping address section when a local pickup shipping method is selected.' => 'Mengalih keluar bahagian alamat penghantaran apabila kaedah penghantaran pengambilan tempatan dipilih.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'Menggantikan alamat penghantaran dengan lokasi titik pengambilan apabila kaedah penghantaran pengambilan tempatan dipilih.','Choose which address to save as the shipping address for local pickup orders.' => 'Pilih alamat yang hendak disimpan sebagai alamat penghantaran untuk pesanan pengambilan tempatan.','Save the selected pickup location' => 'Simpan lokasi pengambilan yang dipilih','Save same as the billing address' => 'Simpan sama seperti alamat pengebilan','Do not save any shipping address' => 'Jangan simpan sebarang alamat penghantaran','Company name field for shipping address' => 'Medan nama syarikat untuk alamat penghantaran','Change visibility for the company name field for the shipping address section on the checkout form.' => 'Tukar keterlihatan untuk medan nama syarikat untuk bahagian alamat penghantaran pada borang pembayaran.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'Jika medan ditetapkan sebagai &quot;pilihan&quot;, yang merupakan keadaan keterlihatan lalai, tiada perubahan akan digunakan untuk membenarkan pemalam lain menggunakan sebarang perubahan yang mereka perlukan.','Hidden (remove field)' => 'Tersembunyi (alih keluar medan)','Optional' => 'Pilihan','Required' => 'Diperlukan','Add shipping phone field to the checkout form.' => 'Tambahkan medan telefon penghantaran pada borang pembayaran.','Choose in which step to display the shipping phone field.' => 'Pilih dalam langkah mana untuk memaparkan medan telefon penghantaran.','Contact step' => 'Langkah kenalan','Billing phone' => 'Mengebil telefon','Add billing phone field to the checkout form.' => 'Tambahkan medan telefon pengebilan pada borang pembayaran.','Choose in which step to display the billing phone field.' => 'Pilih dalam langkah mana untuk memaparkan medan telefon pengebilan.','Show country code beside the flag' => 'Tunjukkan kod negara di sebelah bendera','Show an example of a valid phone number inside phone fields' => 'Tunjukkan contoh nombor telefon yang sah di dalam medan telefon','Do not change placeholders' => 'Jangan tukar ruang letak','Show if not defined' => 'Tunjukkan jika tidak ditakrifkan','Always show' => 'Sentiasa tunjukkan','Order notes' => 'Nota pesanan','Define the visibility of the additional order notes field.' => 'Tentukan keterlihatan medan nota pesanan tambahan.','Gift options' => 'Pilihan hadiah','Allow customers to add a gift message and other gift related options to the order.' => 'Benarkan pelanggan menambah mesej hadiah dan pilihan berkaitan hadiah lain pada pesanan.','Display the gift message as part of the order details table instead of a separate section' => 'Paparkan mesej hadiah sebagai sebahagian daripada jadual butiran pesanan dan bukannya bahagian berasingan','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'Pilihan ini mempengaruhi halaman pengesahan pesanan (halaman terima kasih) dan butiran pesanan pada halaman akaun, e-mel dan slip pembungkusan.','Account matching' => 'Padanan akaun','Enable the account matching feature' => 'Dayakan ciri padanan akaun','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'Kaitkan pesanan pelanggan tetamu dengan akaun sedia ada mereka apabila akaun sudah wujud dengan butiran hubungan pelanggan.','Display message when an account exists with the email address provided' => 'Paparkan mesej apabila akaun wujud dengan alamat e-mel yang diberikan','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'Menggantikan medan penciptaan akaun dengan pemberitahuan dan pilihan untuk log masuk. Dalam sesetengah konteks, mungkin disyorkan untuk membiarkan pilihan ini dilumpuhkan untuk melindungi privasi pelanggan.','Dashboard' => 'Papan pemuka','Integrations' => 'Integrasi','License keys' => 'Kunci lesen','Visit our website for more information about our plugins and add-ons.' => 'Lawati tapak web kami untuk mendapatkan maklumat lanjut tentang pemalam dan alat tambah kami.','Order pay page' => 'Halaman bayaran pesanan','Order pay' => 'Pesanan bayar','Enable order pay page optimizations' => 'Dayakan pengoptimuman halaman bayar pesanan','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'Mengubah reka letak halaman pembayaran pesanan untuk pesanan sedia ada sementara menunggu pembayaran daripada pelanggan.','Add widget areas to the order pay page' => 'Tambahkan kawasan widget pada halaman pembayaran pesanan','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'Kawasan widget ini digunakan untuk menambah simbol amanah dan lencana amanah pada halaman pembayaran pesanan.','Thank you page & order details layout' => 'Terima kasih muka surat &amp; susun atur butiran pesanan','Order details optimizations' => 'Pengoptimuman butiran pesanan','Enable thank you page and order details optimizations' => 'Dayakan pengoptimuman halaman terima kasih dan butiran pesanan','Changes the layout of order details on the thank you page and account pages.' => 'Mengubah reka letak butiran pesanan pada halaman terima kasih dan halaman akaun.','Enable order details customizations on email notifications' => 'Dayakan penyesuaian butiran pesanan pada pemberitahuan e-mel','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'Paparkan bahagian baharu dan tukar susunan bahagian pada pemberitahuan e-mel. Gaya butiran pesanan pada pemberitahuan e-mel kekal tidak berubah.','Thank you page' => 'Halaman terima kasih','These options affect the thank you page, also known as order received or order confirmation pages.' => 'Pilihan ini mempengaruhi halaman terima kasih, juga dikenali sebagai halaman pesanan diterima atau pengesahan pesanan.','Order details layout' => 'Susun atur butiran pesanan','Display the order details with wide layout on the thank you page' => 'Paparkan butiran pesanan dengan susun atur yang luas pada halaman terima kasih','Add widget areas to the thank you page' => 'Tambahkan kawasan widget pada halaman terima kasih','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'Kawasan widget ini digunakan untuk menambah simbol kepercayaan dan lencana kepercayaan pada halaman terima kasih.','Order actions' => 'Perintah tindakan','Choose in which position to display the order actions.' => 'Pilih di kedudukan mana untuk memaparkan tindakan pesanan.','Inside the order overview' => 'Di dalam gambaran keseluruhan pesanan','After the order overview' => 'Selepas gambaran keseluruhan pesanan','After order sections' => 'Selepas bahagian pesanan','Order status' => 'Status pesanan','Display the order status progress bar' => 'Paparkan bar kemajuan status pesanan','Choose in which position to display the section.' => 'Pilih di kedudukan mana untuk memaparkan bahagian tersebut.','After the order overview and payment instructions' => 'Selepas gambaran keseluruhan pesanan dan arahan pembayaran','Before the order items section' => 'Sebelum bahagian barang pesanan','Inside the order items section' => 'Di dalam bahagian item pesanan','After the order items section' => 'Selepas bahagian pesanan barang','On the sidebar' => 'Pada bar sisi','Order downloads' => 'Pesanan muat turun','Gift message' => 'Mesej hadiah','Tools' => 'Alatan','Troubleshooting' => 'Menyelesaikan masalah','Debug options' => 'Pilihan nyahpepijat','Debug mode' => 'Mod nyahpepijat','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'Menggunakan mod nyahpepijat menjejaskan prestasi tapak web. Hanya gunakan pilihan ini semasa menyelesaikan masalah.','Load unminified assets' => 'Muatkan aset yang tidak dikecilkan','Enhanced select fields' => 'Medan pilihan dipertingkatkan','Fix automatic zoom-in on form fields' => 'Betulkan zum masuk automatik pada medan borang','Set <code>font-size</code> inside form fields to 16px' => 'Tetapkan <code>font-size</code> di dalam medan borang kepada 16px','Fluid Checkout' => 'Pembayaran Cecair','Settings' => 'tetapan','Support' => 'Sokongan','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => '<a target="_blank" href="%s">Tingkatkan kepada PRO</a> untuk membuka lebih banyak pilihan.','(PRO)' => '(PRO)','(experimental)' => '(percubaan)','Please verify your phone number.' => 'Sila sahkan nombor telefon anda.','The Bluehost Plugin' => 'Pemalam Bluehost','Custom fields' => 'Medan tersuai','Enable custom shipping email field' => 'Dayakan medan e-mel penghantaran tersuai','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'Apabila didayakan, medan e-mel penghantaran daripada pemalam Bluehost akan ditambahkan pada borang pembayaran.','Captcha Pro by BestWebSoft' => 'Captcha Pro oleh BestWebSoft','Captcha position' => 'Kedudukan Captcha','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'Tentukan kedudukan untuk memaparkan bahagian captcha. Sesetengah kedudukan mungkin tidak berfungsi bergantung pada jenis captcha yang dipilih.','Selecting a pickup point is required before proceeding.' => 'Memilih tempat pengambilan diperlukan sebelum meneruskan.','Pickup point' => 'Titik pengambilan','Pickup point not selected yet.' => 'Tempat pengambilan belum dipilih lagi.','Pickup point:' => 'Tempat pengambilan:','Mailchimp for WooCommerce' => 'Mailchimp untuk WooCommerce','Subscribe checkbox' => 'Langgan kotak semak','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'Gantikan kedudukan untuk kotak semak langgan pada halaman daftar keluar dan sentiasa paparkannya pada langkah kenalan','Before Shipping Address' => 'Sebelum Alamat Penghantaran','(originally "%s")' => '(asalnya &quot;%s&quot;)','After Shipping Address' => 'Selepas Alamat Penghantaran','Selecting a collection point is required when shipping with FermoPoint.' => 'Memilih tempat pengumpulan diperlukan semasa penghantaran dengan FermoPoint.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'Jika disemak memberitahu kesilapan dalam e-mel kepada pengguna. (Ciri ini telah dilumpuhkan kerana Fluid Checkout menawarkan ciri tersebut. Perubahan pada pilihan ini tidak akan berkuat kuasa)','Enable Mail Check: (disabled feature)' => 'Dayakan Semakan Mel: (ciri dilumpuhkan)','Carrier:' => 'Pembawa:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - Pemasaran E-mel WooCommerce','Sign up checkbox position' => 'Daftar kedudukan kotak semak','Move the sign up checkbox to the contact step' => 'Alihkan kotak semak pendaftaran ke langkah kenalan','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'Apabila didayakan, kotak pilihan akan dialihkan ke langkah kenalan secara berasingan daripada lokasi paparan yang ditakrifkan dalam tetapan pemalam Sendinblue.','Theme Betheme' => 'Tema Betheme','Checkout progress' => 'Kemajuan pembayaran','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'Keluarkan bahagian langkah daftar keluar dari Betheme pada halaman pembayaran, troli dan pesanan yang diterima.','Theme Fennik' => 'Tema Fennik','Breadcrumbs' => 'Serbuk roti','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'Keluarkan bahagian serbuk roti daripada tema Fennik apabila menggunakan pengepala dan pengaki Fluid Checkout.','Theme Go' => 'Tema Pergi','My account layout' => 'Susun atur akaun saya','Enable wide layout on "My account" page.' => 'Dayakan reka letak yang luas pada halaman &quot;Akaun saya&quot;.','Theme Impreza' => 'Tema Impreza','Header' => 'Pengepala','Spacing for site header at the checkout page (in pixels)' => 'Jarak untuk pengepala tapak di halaman pembayaran (dalam piksel)','Only applicable when using the Impreza theme header at the checkout page.' => 'Hanya terpakai apabila menggunakan pengepala tema Impreza di halaman pembayaran.','Theme Kapee' => 'Tema Kapee','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'Keluarkan bahagian langkah daftar keluar dari tema Kapee pada halaman pembayaran, troli dan pesanan yang diterima.','Theme Porto' => 'Tema Porto','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'Keluarkan bahagian langkah daftar keluar dari tema Porto pada halaman pembayaran, troli dan pesanan yang diterima.','Theme Pressmart' => 'Pressmart Tema','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'Keluarkan bahagian langkah daftar keluar dari tema Pressmart pada halaman pembayaran, troli dan pesanan yang diterima.','Theme The Gem' => 'Tema Permata','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'Keluarkan bahagian langkah daftar keluar daripada tema Permata apabila menggunakan pengepala dan pengaki Fluid Checkout.','Theme Woodmart' => 'Tema Woodmart','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'Keluarkan bahagian langkah daftar keluar daripada tema Woodmart apabila menggunakan pengepala dan pengaki Fluid Checkout.','Checkout options' => 'Pilihan daftar keluar','Disable the theme checkout options' => 'Lumpuhkan pilihan daftar keluar tema','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'Pilihan memaparkan imej produk, medan kuantiti, butang alih keluar dan pautan ke halaman produk yang ditambahkan oleh tema dilumpuhkan secara lalai.','Theme Atomion' => 'Tema Atomion','Order progress' => 'Kemajuan pesanan','Display order progress from the theme' => 'Paparkan kemajuan pesanan daripada tema','Display the form field labels visible on the page' => 'Paparkan label medan borang yang boleh dilihat pada halaman','It is recommended to keep this option enabled for a better user experience.' => 'Adalah disyorkan untuk memastikan pilihan ini didayakan untuk pengalaman pengguna yang lebih baik.','Theme ZK Nito' => 'Tema ZK Nito','Add extra fields to the checkout form' => 'Tambahkan medan tambahan pada borang pembayaran','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'Menambahkan e-mel penghantaran tambahan dan medan telefon penghantaran ke bahagian alamat penghantaran.','Go to the home page' => 'Pergi ke halaman utama','Skip to content' => 'Langkau ke kandungan','Create an account' => 'Buat akaun','Log in to your account' => 'Log masuk ke akaun anda','Already have an account?' => 'Sudah mempunyai akaun?','Logged in as %1$s. <a href="%2$s">Log out</a>' => 'Log masuk sebagai %1$s. <a href="%2$s">Log keluar</a>','Your order has a total amount due of %s. No further payment is needed.' => 'Pesanan anda mempunyai jumlah terhutang sebanyak %s. Tiada bayaran lanjut diperlukan.','Close and continue with checkout' => 'Tutup dan teruskan dengan pembayaran','Continue' => 'Teruskan','Parcel terminal' => 'Terminal bungkusan','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>Widget ini telah digantikan dengan Fluid Checkout.</p><p> Apabila menggunakan Fluid Checkout, halaman daftar keluar perlu menggunakan kod pendek WooCommerce asal <code>[woocommerce_checkout]</code> untuk berfungsi dengan betul.</p><p> Untuk maklumat lanjut, lawati dokumentasi Fluid Checkout.</p>','Theme The7' => 'Tema The7','Additional header sections' => 'Bahagian pengepala tambahan','Output additional header sections if enabled in the theme settings.' => 'Keluarkan bahagian pengepala tambahan jika didayakan dalam tetapan tema.','More information' => 'Maklumat lanjut','Pick a Locker' => 'Pilih loker','Page template' => 'templat halaman','Use `Order confirmation` page template for block-based themes' => 'Gunakan templat halaman `Pengesahan pesanan` untuk tema berasaskan blok','Only applies when using a block-based theme.' => 'Hanya terpakai apabila menggunakan tema berasaskan blok.','WooCommerce Stripe Gateway' => 'Gerbang Jalur WooCommerce','Payment form' => 'Borang pembayaran','Apply styles to the Stripe payment form fields' => 'Gunakan gaya pada medan borang pembayaran Stripe','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'Apabila didayakan, Fluid Checkout akan menggunakan gaya yang dioptimumkan untuk keserasian dengan pemalam. Anda mungkin mahu melumpuhkan ini jika anda menggunakan gaya tersuai untuk medan borang pembayaran Stripe.','Theme Nyture' => 'Tema Nyture','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'Keluarkan bahagian langkah daftar keluar daripada tema Nyture apabila menggunakan Fluid Checkout.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'Membenarkan pelanggan membuat pembayaran untuk pesanan yang sama ada dibuat secara manual oleh pentadbir kedai atau tidak diselesaikan semasa daftar keluar.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'Pemalam WooCommerce Checkout Manager oleh Quadlayers tidak serasi dengan Fluid Checkout','Company name field for billing address' => 'Medan nama syarikat untuk alamat pengebilan','Change visibility for the company name field for the billing address section on the checkout form.' => 'Tukar keterlihatan untuk medan nama syarikat untuk bahagian alamat pengebilan pada borang pembayaran.','Theme Bookshelf' => 'Rak Buku Tema','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'Keluarkan bahagian langkah daftar keluar daripada tema Rak Buku apabila menggunakan Fluid Checkout.','Account password' => 'Kata laluan akaun','An account will be created with the information provided at checkout when completing the order.' => 'Akaun akan dibuat dengan maklumat yang diberikan semasa pembayaran semasa menyelesaikan pesanan.','Choose the style of the progress bar.' => 'Pilih gaya bar kemajuan.','Bars' => 'Bar','Theme Ireca' => 'Tema Ireca','WooCommerce page layout' => 'Susun atur halaman WooCommerce','Force wide layout on WooCommerce pages' => 'Paksa susun atur luas pada halaman WooCommerce','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'Ini memastikan bahagian kandungan tidak terlalu sempit pada halaman WooCommerce termasuk daftar keluar, troli, pesanan diterima, bayaran pesanan dan halaman akaun.','WooCommerce Smart Coupons' => 'Kupon Pintar WooCommerce','Position on checkout page' => 'Kedudukan pada halaman pembayaran','Choose where to display the available coupons section on the checkout page.' => 'Pilih tempat untuk memaparkan bahagian kupon yang tersedia pada halaman pembayaran.','Before the progress bar' => 'Sebelum bar kemajuan','After the progress bar' => 'Selepas bar kemajuan','Before coupon codes section' => 'Sebelum bahagian kod kupon','Format phone numbers according to the rules for each country.' => 'Format nombor telefon mengikut peraturan untuk setiap negara.','Use precise phone number validation' => 'Gunakan pengesahan nombor telefon yang tepat','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'Ini ialah ciri percubaan dan mungkin tidak berfungsi seperti yang diharapkan dalam semua persediaan. Gunakannya dengan berhati-hati.','Phone number validation types used when precise validation is enabled.' => 'Jenis pengesahan nombor telefon digunakan apabila pengesahan tepat didayakan.','Mobile' => 'Mudah alih','Fixed line' => 'Talian tetap','Toll free' => 'Percuma tol','Or' => 'Atau','Contact' => 'Hubungi','Multi step' => 'Pelbagai langkah','2 columns' => '2 lajur','1 column' => '1 lajur','Before checkout steps' => 'Sebelum langkah pembayaran','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => 'Apabila menggunakan susun atur pembayaran <em>&quot;1 lajur&quot;,</em> pilihan ini sentiasa ditetapkan kepada <em>&quot;Sebelum langkah pembayaran&quot;</em> dan juga terpakai pada paparan desktop.','Position for the extra order summary section on mobile.' => 'Jawatan untuk bahagian ringkasan pesanan tambahan di telefon bimbit.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => 'Pilihan <em>&quot;Pengepala di tapak&quot;</em> hanya terpakai apabila menggunakan pengepala bebas gangguan.','On the site header (requires distraction-free header)' => 'Pada pengepala tapak (memerlukan pengepala bebas gangguan)','Initial state for the expansible order summary section on mobile.' => 'Keadaan awal untuk bahagian ringkasan pesanan yang boleh dikembangkan pada mudah alih.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'Kami mengesyorkan untuk menetapkannya sebagai <em>dikembangkan</em> untuk negara-negara berikut disebabkan oleh keperluan kawal selia: <strong>Jerman</strong> , <strong>Austria</strong> , <strong>Switzerland</strong> , <strong>Belanda</strong> , <strong>Poland</strong> , <strong>Belgium</strong> dan <strong>Perancis</strong> .','Collapsed' => 'Runtuh','Expanded' => 'Diperluas','Do not show' => 'Jangan tunjukkan','yes' => 'ya','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Medan telefon penghantaran mungkin dipaksa sebagai &quot;diperlukan&quot; jika bahagian alamat pengebilan dipaparkan selepas bahagian alamat penghantaran dan medan telefon pengebilan ditetapkan sebagai &quot;diperlukan&quot;. Ini diperlukan untuk memastikan alamat penghantaran boleh disalin ke alamat pengebilan apabila pilihan tersebut ditanda, jika tidak, pelanggan mungkin tidak dapat melengkapkan borang pembayaran.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Medan telefon pengebilan mungkin dipaksa sebagai &quot;diperlukan&quot; jika bahagian alamat pengebilan dipaparkan sebelum bahagian alamat penghantaran dan medan telefon penghantaran ditetapkan sebagai &quot;diperlukan&quot;. Ini diperlukan untuk memastikan alamat penghantaran boleh disalin ke alamat pengebilan apabila pilihan tersebut ditanda, jika tidak, pelanggan mungkin tidak dapat melengkapkan borang pembayaran.','Settings profiles' => 'Profil tetapan','Settings profile' => 'Profil tetapan','You do not have permission to perform this action.' => 'Anda tidak mempunyai kebenaran untuk melakukan tindakan ini.','You do not have permission to activate plugins.' => 'Anda tidak mempunyai kebenaran untuk mengaktifkan pemalam.','Missing plugin.' => 'Plugin hilang.','Plugin activated.' => 'Plugin diaktifkan.','The following changes will be applied:' => 'Perubahan berikut akan dikenakan:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'Sejak Fluid Checkout 5.0, tetapan disimpan secara berbeza. Pilihan legasi masih disimpan dalam pangkalan data untuk membolehkan penurunan taraf kepada versi sebelumnya jika perlu.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'Kedai anda telah beroperasi selama kira-kira 2 minggu pada tetapan baharu supaya anda boleh membersihkan pilihan legasi yang disimpan dalam pangkalan data. Sila ambil perhatian bahawa selepas pembersihan, jika anda perlu menurunkan taraf kepada versi pemalam sebelumnya, ia akan menggunakan nilai lalai untuk semua tetapan.','Fluid Checkout settings cleanup' => 'Pembersihan tetapan Pemeriksaan Cecair','Delete leftover options' => 'Padam pilihan yang tinggal','Help us improve Fluid Checkout' => 'Bantu kami menambah baik Pemeriksaan Cecair','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'Kongsikan laporan persekitaran tapak tanpa nama dengan Fluid Checkout untuk mendapatkan sokongan yang lebih pantas dan membantu kami meningkatkan keserasian serta mengukur impak. Tiada data pelanggan, pengguna atau sensitif disertakan. Anda boleh memilih apa yang dikongsi pada bila-bila masa daripada tetapan Alatan.','Enable site environment reports' => 'Dayakan laporan persekitaran tapak','Review settings' => 'Semak tetapan','This preview has expired. Reload the admin page to start a new preview.' => 'Pratonton ini telah tamat tempoh. Muat semula halaman pentadbir untuk memulakan pratonton baharu.','Preview expired' => 'Pratonton tamat tempoh','Orders cannot be placed in the preview.' => 'Pesanan tidak boleh dibuat dalam pratonton.','Logging in is not available in the preview.' => 'Log masuk tidak tersedia dalam pratonton.','Accounts cannot be created in the preview.' => 'Akaun tidak boleh dibuat dalam pratonton.','Requests to other sites are blocked in the preview.' => 'Permintaan ke tapak lain disekat dalam pratonton.','Processing…' => 'Memproses…','Something went wrong. Please try again.' => 'Ada masalah. Sila cuba lagi.','Activate plugin' => 'Aktifkan pemalam','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO - Pakej pembayaran lengkap','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'Semua ciri PRO + semua tambahan, satu harga. Templat reka bentuk, halaman troli dan pesanan yang diterima yang dioptimumkan, pemadanan akaun dan banyak lagi.','Optimized order pay page' => 'Halaman pembayaran pesanan yang dioptimumkan','Express checkout buttons from supported payment methods' => 'Butang pembayaran ekspres daripada kaedah pembayaran yang disokong','Delayed account creation' => 'Penciptaan akaun tertangguh','Address autocomplete with Google Maps APIs' => 'Pelengkapan automatik alamat dengan API Peta Google','Multiple saved addresses with the address book' => 'Berbilang alamat yang disimpan dengan buku alamat','EU-VAT assistant' => 'Pembantu EU-VAT','Hide this section' => 'Sembunyikan bahagian ini','Learn more' => 'Ketahui lebih lanjut','Get early access' => 'Dapatkan akses awal','Activate add-on' => 'Aktifkan alat tambah','Get more out of your checkout journey' => 'Dapatkan lebih manfaat daripada perjalanan pembayaran anda','Test API key' => 'Kunci API ujian','Guided setup' => 'Persediaan berpandu','Options' => 'Pilihan','Set up layout and design on the <a href="%s">checkout options</a>.' => 'Sediakan susun atur dan reka bentuk pada <a href="%s">pilihan pembayaran</a> .','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'Dayakan daftar keluar tetamu dan/atau semak <a href="%s">tetapan akaun pelanggan</a> .','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'Dayakan halaman <a href="%3$s">pembayaran</a> <a href="%1$s">troli</a> , <a href="%2$s">terima kasih</a> dan pesanan yang dioptimumkan.','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Dayakan <a href="%s">pelengkapan automatik alamat</a> daripada Peta Google.','Enable multiple saved addresses with <a href="%s">address book</a>.' => 'Dayakan berbilang alamat yang disimpan dengan <a href="%s">buku alamat</a> .','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'Semak sama ada terdapat sebarang <a href="%s">pilihan integrasi</a> yang tersedia untuk tema atau pemalam lain yang telah anda pasang.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'Dapatkan sokongan yang lebih pantas dan bantu kami meningkatkan keserasian serta mengukur impak. <a href="%s">Dayakan penjejakan penggunaan</a> daripada tetapan alat.','Missing settings tab.' => 'Tab tetapan tiada.','Getting started' => 'Bermula','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>Bagus! Halaman pembayaran anda kini berjalan di Fluid Checkout.</strong> Berikut adalah beberapa langkah untuk bermula:','Completed' => 'Selesai','Preview report data' => 'Pratonton data laporan','Send now' => 'Hantar sekarang','Auto-detect' => 'Kesan automatik','Afrikaans' => 'Bahasa Afrikaans','Albanian' => 'Albania','Amharic' => 'Amharic','Arabic' => 'Bahasa Arab','Armenian' => 'Armenia','Azerbaijani' => 'Azerbaijan','Basque' => 'Basque','Belarusian' => 'Bahasa Belarus','Bengali' => 'Bengali','Bosnian' => 'Bosnia','Bulgarian' => 'Bahasa Bulgaria','Burmese' => 'Burma','Catalan' => 'Bahasa Catalan','Chinese' => 'Cina','Chinese (Simplified)' => 'Bahasa Cina (Ringkas)','Chinese (Hong Kong)' => 'Cina (Hong Kong)','Chinese (Traditional)' => 'Cina (Tradisional)','Croatian' => 'Bahasa Croatia','Czech' => 'Czech','Danish' => 'Bahasa Denmark','Dutch' => 'Belanda','English' => 'Bahasa Inggeris','English (Australian)' => 'Bahasa Inggeris (Australia)','English (Great Britain)' => 'Inggeris (Great Britain)','Estonian' => 'Estonia','Farsi' => 'Parsi','Finnish' => 'Bahasa Finland','Filipino' => 'Bahasa Filipina','French' => 'Perancis','French (Canadian)' => 'Perancis (Kanada)','Galician' => 'Galicia','Georgian' => 'Georgia','German' => 'Jerman','Greek' => 'Yunani','Gujarati' => 'Gujarati','Hebrew' => 'Ibrani','Hindi' => 'Hindi','Hungarian' => 'Bahasa Hungary','Icelandic' => 'Bahasa Iceland','Indonesian' => 'Bahasa Indonesia','Italian' => 'Itali','Japanese' => 'Bahasa Jepun','Kannada' => 'Kannada','Kazakh' => 'Kazakh','Khmer' => 'Khmer','Korean' => 'Bahasa Korea','Kyrgyz' => 'Kirgiz','Lao' => 'Lao','Latvian' => 'Bahasa Latvia','Lithuanian' => 'Bahasa Lithuania','Macedonian' => 'Macedonia','Malay' => 'Bahasa Melayu','Malayalam' => 'Malayalam','Marathi' => 'Marathi','Mongolian' => 'Mongolia','Nepali' => 'Nepal','Norwegian' => 'Bahasa Norway','Polish' => 'Poland','Portuguese' => 'Portugis','Portuguese (Brazil)' => 'Portugis (Brazil)','Portuguese (Portugal)' => 'Portugis (Portugal)','Punjabi' => 'Punjabi','Romanian' => 'Bahasa Romania','Russian' => 'Rusia','Serbian' => 'Bahasa Serbia','Sinhalese' => 'Bahasa Sinhala','Slovak' => 'Slovakia','Slovenian' => 'Bahasa Slovenia','Spanish' => 'Bahasa Sepanyol','Spanish (Latin America)' => 'Sepanyol (Amerika Latin)','Swahili' => 'Bahasa Swahili','Swedish' => 'Sweden','Tamil' => 'Bahasa Tamil','Telugu' => 'Telugu','Thai' => 'Bahasa Thai','Turkish' => 'Turki','Ukrainian' => 'Ukraine','Urdu' => 'Bahasa Urdu','Vietnamese' => 'Vietnam','Zulu' => 'Zulu','Google address autocomplete' => 'Autolengkap alamat Google','Google Places API version' => 'Versi API Tempat Google','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Pilih versi API Tempat Google yang hendak digunakan. Kami mengesyorkan agar anda beralih kepada API Tempat baharu secepat mungkin.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'Kami mengesyorkan penggunaan &quot;Places API (Baharu)&quot; berkuat kuasa 1 Mac 2025. Google akan memindahkan versi &quot;Places API (Baharu)&quot; kepada status Legacy, bermakna anda tidak lagi dapat mendayakan perkhidmatan ini untuk kunci API baharu dan versi API tersebut akhirnya tidak akan tersedia lagi. Akaun sedia ada yang sudah menggunakan Legacy API mungkin terus berfungsi tanpa gangguan.','(Recommended)' => '(Disyorkan)','Google API key' => 'Kunci API Google','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'Tampalkan kunci API Google anda dan gunakan butang ujian untuk mengesahkan ia berfungsi untuk laman web ini. Pastikan kunci tersebut sah dan dibenarkan untuk domain anda, jika tidak, medan alamat mungkin disekat dan menghalang pelanggan daripada menyelesaikan pesanan mereka.','Enable Google address autocomplete' => 'Dayakan pelengkapan automatik alamat Google','Enable address autocompletion using the Google Maps APIs.' => 'Dayakan pelengkapan automatik alamat menggunakan API Peta Google.','Google API language' => 'Bahasa API Google','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'Bahasa ini akan digunakan untuk memaparkan cadangan alamat API Google Places dan alamat juga akan dilengkapkan secara automatik dalam bahasa ini.','Result types' => 'Jenis hasil','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Biarkan kosong untuk menerima sebarang jenis keputusan, yang biasanya menghasilkan keputusan yang lebih sepadan. <a href="%s" target="_blank">Lihat dokumentasi untuk butiran lanjut</a> .<br> Pilih sehingga 5 jenis hasil carian alamat untuk mengembalikan medan autolengkap alamat.<br> Lawati dokumentasi Peta Google untuk mengetahui lebih lanjut tentang <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">jenis yang disokong</a> .','Result types (Legacy API)' => 'Jenis hasil (API Legasi)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Jenis hasil carian alamat yang hendak dikembalikan apabila menggunakan Places API (Legacy).<br> Lawati dokumentasi API Tempat Google Legacy untuk mengetahui lebih lanjut tentang <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">jenis yang disokong</a> .','Company fields' => 'Medan syarikat','Enable autocomplete for the company name if available' => 'Dayakan autolengkap untuk nama syarikat jika tersedia','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Dayakan pelengkapan automatik medan syarikat dengan maklumat nama syarikat apabila dikembalikan daripada API Peta Google.','Business search' => 'Carian perniagaan','Enable search for businesses in the company field' => 'Dayakan carian untuk perniagaan dalam medan syarikat','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'Dayakan cadangan alamat yang berkaitan dengan perniagaan semasa menaip dalam medan syarikat, kemudian lengkapkan semua medan alamat secara automatik apabila perniagaan dipilih daripada cadangan.','Company result types' => 'Jenis hasil syarikat','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Pilih sehingga 5 jenis hasil carian alamat untuk dikembalikan pada medan syarikat autolengkap.<br> Nilai yang disyorkan ialah <code>establishment</code> , yang merangkumi kebanyakan jenis perniagaan.<br> Biarkan kosong untuk menerima sebarang jenis keputusan, termasuk keputusan yang tidak berkaitan dengan perniagaan.<br> Lawati dokumentasi Peta Google untuk mengetahui lebih lanjut tentang <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">jenis yang disokong</a> .','Google logo' => 'Logo Google','Show text and logo "Powered by Google"' => 'Tunjukkan teks dan logo &quot;Dikuasakan oleh Google&quot;','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'Apabila ditanda, teks dan logo &quot;Dikuasakan oleh Google&quot; akan dipaparkan di bahagian bawah kotak cadangan pelengkapan automatik alamat.','Brasil API address autocomplete' => 'Alamat API Brasil autolengkap','Brasil API' => 'API Brazil','Enable Brasil API address autocomplete for CEP fields' => 'Dayakan autolengkap alamat API Brasil untuk medan CEP','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'Gunakan API Brasil untuk mendapatkan dan mengisi alamat secara automatik menggunakan medan CEP/Poskod. Hanya berkaitan untuk alamat Brazil.','API version' => 'Versi API','Choose which version of the Brasil API CEP method to use.' => 'Pilih versi kaedah CEP API Brasil yang hendak digunakan.','Address book migration' => 'Migrasi buku alamat','WooCommerce addresses' => 'Alamat WooCommerce','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'Salin alamat penghantaran dan pengebilan sedia ada daripada WooCommerce ke dalam buku alamat pelanggan.','Enable the address book feature' => 'Dayakan ciri buku alamat','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'Benarkan pelanggan menyimpan berbilang alamat dan tentukan alamat lalai yang akan digunakan untuk penghantaran dan pengebilan.','Address labels' => 'Label alamat','Allow customers to add a custom label for each address' => 'Benarkan pelanggan menambah label tersuai untuk setiap alamat','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'Label alamat memudahkan pelanggan membezakan antara alamat yang disimpan (iaitu: &quot;Rumah Ibu&quot;). Label alamat adalah peribadi kepada pelanggan dan tidak akan dipaparkan atau dicetak pada halaman butiran pesanan atau invois.','Display layout' => 'Susun atur paparan','Choose how saved addresses are displayed at checkout and on the cart.' => 'Pilih cara alamat yang disimpan dipaparkan semasa pembayaran dan pada troli.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'Terpakai semasa pembayaran dan pada troli. Alamat yang disimpan pada halaman akaun sentiasa menggunakan susun atur kad.','Address cards' => 'Kad alamat','Address list' => 'Senarai alamat','Dropdown field' => 'Medan lungsur turun','Address search' => 'Carian alamat','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'Tunjukkan penapis carian alamat pada bahagian hadapan apabila pelanggan mempunyai sekurang-kurangnya bilangan alamat yang disimpan ini.','Not used when display layout is set to dropdown field.' => 'Tidak digunakan apabila susun atur paparan ditetapkan kepada medan lungsur turun.','Addresses' => 'Alamat','Enable cart page optimizations to see more options' => 'Dayakan pengoptimuman halaman troli untuk melihat lebih banyak pilihan','Sticky order summary' => 'Ringkasan pesanan lekit','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Pilih kedudukan tempat untuk memaparkan bahagian kod kupon pada halaman troli. Hanya terpakai apabila troli AJAX diaktifkan dan jika penggunaan kod kupon diaktifkan dalam tetapan WooCommerce.','Layout of cross-sell' => 'Susun atur jualan silang','Cross-sells displayed' => 'Jualan silang dipaparkan','Items' => 'Barangan','Cart page optimization' => 'Pengoptimuman halaman troli','Give your cart the same clear, conversion-focused layout as your checkout.' => 'Berikan troli anda susun atur yang jelas dan berfokuskan penukaran yang sama seperti pembayaran anda.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'Padankan susun atur troli dengan halaman pembayaran untuk perjalanan pembelian yang konsisten.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'Pastikan troli sentiasa dikemas kini di latar belakang, tiada muat semula halaman penuh apabila kuantiti berubah.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'Letakkan kod kupon, penghantaran dan jualan silang tepat di tempat yang paling banyak ditukar.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'Pastikan ringkasan pesanan kelihatan semasa menatal dan tambahkan simbol kepercayaan di tempat pembeli memerlukan jaminan.','Columns' => 'Lajur','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'Gaya umum untuk langkah pembayaran, ringkasan pesanan dan bahagian lain. Terpakai pada halaman pembayaran lain, troli, terima kasih (pesanan diterima) dan lihat halaman pesanan.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => 'Apabila menggunakan susun atur <em>&quot;1 lajur&quot;</em> dengan templat reka bentuk <em>&quot;Pisah&quot;</em> , lajur kanan hanya dipaparkan jika kawasan widget bar sisi halaman aktif (Bar Sisi Pembayaran, Bar Sisi Troli atau Bar Sisi Pesanan Diterima). Jika tidak, halaman kekal sebagai satu lajur dengan gaya Pisah.','Split column background' => 'Latar belakang lajur berpecah','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'Pilih warna latar belakang untuk lajur sekunder Reka bentuk Split. Biarkan kosong untuk menggunakan warna latar belakang ringkasan pesanan.','Page templates' => 'Templat halaman','Checkout template' => 'Templat pembayaran','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'Disyorkan untuk kurang gangguan semasa pembayaran. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Baca kajian tentang pengabaian troli</a> .','Sticky progress bar' => 'Bar kemajuan melekit','Progress bar style' => 'Gaya bar kemajuan','Order totals' => 'Jumlah pesanan','Background color' => 'Warna latar belakang','Action link' => 'Pautan tindakan','Mobile order summary' => 'Ringkasan pesanan mudah alih','Mobile initial state' => 'Keadaan awal mudah alih','Enable editing cart items at checkout' => 'Dayakan pengeditan item troli semasa pembayaran','Allow customers to change product quantities or remove items directly at the checkout page.' => 'Benarkan pelanggan menukar kuantiti produk atau mengalih keluar item terus di halaman pembayaran.','Cart item errors' => 'Ralat item troli','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Hanya terpakai apabila kod kupon dipaparkan sebagai bahagian berasingan pada halaman pembayaran atau troli, dan jika penggunaan kod kupon didayakan dalam tetapan WooCommerce.','Coupon codes position' => 'Kedudukan kod kupon','Apply coupon button' => 'Butang guna kupon','Select style of the "apply coupon" button.' => 'Pilih gaya butang &quot;gunakan kupon&quot;.','Address line 2' => 'Baris alamat 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'Tetapan ini dikongsi antara bahagian Daftar Keluar dan Pengambilan Tempatan. Pada bahagian Pengambilan Tempatan, ia juga menentukan sama ada pemilih Hantar/Ambilan dipaparkan di dalam bahagian kaedah penghantaran (sebelum alamat) atau sebagai bahagian berasingan (selepas).','Customer accounts' => 'Akaun pelanggan','Guest checkout' => 'Daftar keluar tetamu','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'Pilihan daftar keluar tetamu, log masuk dan penciptaan akaun daripada halaman tetapan Akaun WooCommerce. Ia diuruskan di sini untuk kemudahan anda, jadi anda boleh menggunakan nilai yang berbeza bagi setiap profil tetapan.','Allow customers to checkout without an account' => 'Benarkan pelanggan membuat pembayaran tanpa akaun','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => '<strong>Disyorkan</strong> supaya pelanggan tidak diminta membuat akaun atau log masuk semasa pembayaran, yang boleh menurunkan kadar penukaran.','When disabled, customers must log in or create an account to complete the purchase.' => 'Apabila dilumpuhkan, pelanggan mesti log masuk atau membuat akaun untuk melengkapkan pembelian.','Login at checkout' => 'Log masuk semasa pembayaran','Enable log-in during checkout' => 'Dayakan log masuk semasa pembayaran','Show a link for returning customers to log in from the checkout page.' => 'Tunjukkan pautan untuk pelanggan yang kembali untuk log masuk dari halaman pembayaran.','Account creation' => 'Penciptaan akaun','Allow customers to create an account during checkout' => 'Benarkan pelanggan membuat akaun semasa pembayaran','Customers can create an account before placing their order.' => 'Pelanggan boleh membuat akaun sebelum membuat pesanan.','Allow customers to create an account from the My account page' => 'Benarkan pelanggan membuat akaun daripada halaman Akaun saya','Customers can register a new account from the My account page.' => 'Pelanggan boleh mendaftar akaun baharu dari halaman Akaun Saya.','Username' => 'Nama pengguna','Generate from customer\'s name' => 'Jana daripada nama pelanggan','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => '<strong>Disyorkan</strong> supaya pelanggan tidak diminta memilih nama pengguna semasa pembayaran, yang boleh menurunkan kadar penukaran.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'Nama pengguna dijana daripada nama pelanggan atau daripada alamat e-mel apabila nama tidak boleh digunakan.','Password' => 'Kata Laluan','Send password setup link' => 'Hantar pautan persediaan kata laluan','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => '<strong>Disyorkan</strong> supaya pelanggan tidak diminta menetapkan kata laluan semasa pembayaran, yang boleh menurunkan kadar penukaran.','Customers receive an email to create their password securely.' => 'Pelanggan menerima e-mel untuk mencipta kata laluan mereka dengan selamat.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'Benarkan pelanggan berdaftar melengkapkan pembayaran tanpa log masuk dan kaitkan pesanan dengan akaun sedia ada mereka apabila butiran hubungan sepadan.','Existing account message' => 'Mesej akaun sedia ada','Let customers create an account after placing their order, from the thank you page.' => 'Benarkan pelanggan membuat akaun selepas membuat pesanan mereka, dari halaman terima kasih.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'Pilihan dalam bahagian ini tersedia apabila daftar keluar tetamu dan pemadanan akaun diaktifkan. Dayakan kedua-dua ciri di atas untuk mengkonfigurasi penciptaan akaun yang tertangguh.','Enable delayed account creation' => 'Dayakan penciptaan akaun yang tertangguh','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'Dayakan penciptaan akaun yang tertangguh apabila kedua-dua daftar keluar tetamu dan pemadanan akaun diaktifkan.','Section position' => 'Kedudukan bahagian','Before customer details section' => 'Bahagian butiran pelanggan sebelum','After customer details section' => 'Selepas bahagian butiran pelanggan','Account creation benefits' => 'Faedah penciptaan akaun','Leaving the field empty will display the default text.' => 'Membiarkan medan kosong akan memaparkan teks lalai.','Inline buttons' => 'Butang sebaris','Required fields' => 'Medan yang diperlukan','Enable gift message fields at checkout' => 'Dayakan medan mesej hadiah semasa pembayaran','Expanded gift message' => 'Mesej hadiah yang dikembangkan','Display gift message field always expanded' => 'Paparkan medan mesej hadiah sentiasa dikembangkan','Gift message in order details' => 'Mesej hadiah dalam butiran pesanan','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'Tiada integrasi tersedia pada bahagian ini buat masa ini. Pilihan yang berkaitan dengan setiap pemalam dan tema hanya akan muncul di sini apabila pemalam atau tema tersebut diaktifkan.','Phone fields' => 'Medan telefon','Field visibility' => 'Keterlihatan lapangan','Field position' => 'Kedudukan padang','Phone country code & validation' => 'Kod negara telefon &amp; pengesahan','Country' => 'Negara','Enable country on phone fields' => 'Dayakan medan negara pada telefon','Filter countries for shipping or billing' => 'Tapis negara untuk penghantaran atau pengebilan','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'Hadkan pemilih negara pada setiap medan telefon kepada negara yang dibenarkan untuk penghantaran atau pengebilan di kedai anda.','Validation' => 'Pengesahan','Enable simple validation based on country rules' => 'Dayakan pengesahan mudah berdasarkan peraturan negara','Checks that the phone number is valid for the selected country, including country code and length.' => 'Memeriksa sama ada nombor telefon sah untuk negara yang dipilih, termasuk kod negara dan panjangnya.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'Semakan yang lebih ketat bahawa nombor tersebut adalah mudah alih, talian tetap atau jenis lain yang diterima untuk negara yang dipilih. Mungkin menolak beberapa nombor yang sah.','Validation types' => 'Jenis pengesahan','Placeholders' => 'Pemegang tempat','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'Tiada kunci lesen untuk diuruskan pada masa ini. Kunci lesen akan muncul di sini apabila pemalam atau alat tambah Fluid Checkout berlesen aktif.','Default delivery type' => 'Jenis penghantaran lalai','Choose which delivery type will be selected by default.' => 'Pilih jenis penghantaran yang akan dipilih secara lalai.','Shipping zone fields' => 'Medan zon penghantaran','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'Pilih medan yang akan dipaparkan untuk medan penapis zon penghantaran pengambilan tempatan. Biarkan kosong untuk menunjukkan semua pilihan yang tersedia.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'Medan ini akan dipaparkan sebagai penapis untuk kaedah penghantaran pengambilan tempatan. Sesetengah medan mungkin masih muncul semasa pembayaran apabila tidak dipilih di sini, jika pemalam yang serasi memerlukannya berfungsi dengan baik.','Order shipping address' => 'Alamat penghantaran pesanan','Order pay page optimization' => 'Pengoptimuman halaman pembayaran pesanan','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'Berikan pesanan yang belum dibayar susun atur yang jelas dan berfokuskan penukaran yang sama seperti pembayaran.','Optimize the layout of the order pay page for orders pending payment.' => 'Optimumkan susun atur halaman pembayaran pesanan untuk pesanan yang sedang menunggu pembayaran.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'Padankan pengalaman pembayaran pesanan dengan pembayaran anda untuk perjalanan pembelian yang konsisten.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'Tambahkan simbol dan lencana kepercayaan di tempat pembeli memerlukan jaminan sebelum membayar.','Thank you page optimization' => 'Pengoptimuman halaman terima kasih','Make the thank you page and order details clearer for customers after they buy.' => 'Jadikan halaman terima kasih dan butiran pesanan lebih jelas untuk pelanggan selepas mereka membeli.','Optimize the thank you page and account order details with a clearer layout.' => 'Optimumkan halaman terima kasih dan butiran pesanan akaun dengan susun atur yang lebih jelas.','Show order status progress, actions, downloads, and notes where they make sense.' => 'Tunjukkan kemajuan status pesanan, tindakan, muat turun dan nota di tempat yang sesuai.','Customize order details sections on email notifications.' => 'Sesuaikan bahagian butiran pesanan pada pemberitahuan e-mel.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'Tambahkan simbol dan lencana kepercayaan di tempat pembeli memerlukan jaminan selepas pembelian.','Email notifications' => 'Pemberitahuan e-mel','Enable thank you page and order details optimizations to see more options' => 'Dayakan halaman terima kasih dan pengoptimuman butiran pesanan untuk melihat lebih banyak pilihan','Use wide layout on thank you page' => 'Gunakan susun atur yang luas pada halaman terima kasih','These options affect the thank you page, view order details on account pages and on email notifications.' => 'Pilihan ini mempengaruhi halaman terima kasih, melihat butiran pesanan pada halaman akaun dan pada pemberitahuan e-mel.','Save settings' => 'Simpan tetapan','Docs' => 'Dokumen','Cart' => 'Troli','Thank you' => 'Terima kasih','Address autocomplete' => 'Alamat autolengkap','Trust badges' => 'Lencana amanah','You do not have permission to save these settings.' => 'Anda tidak mempunyai kebenaran untuk menyimpan tetapan ini.','Invalid save request.' => 'Permintaan simpan tidak sah.','Your settings have been saved.' => 'Tetapan anda telah disimpan.','Saving...' => 'Menyimpan...','Settings could not be saved. Please try again.' => 'Tetapan tidak dapat disimpan. Sila cuba lagi.','Dismiss notice' => 'Notis penolakan','Open settings menu' => 'Buka menu tetapan','Close settings menu' => 'Tutup menu tetapan','Preview' => 'Pratonton','Expand preview' => 'Kembangkan pratonton','Collapse preview' => 'Lipat pratonton','Show header and footer' => 'Tunjukkan pengepala dan pengaki','Hide header and footer' => 'Sembunyikan pengepala dan pengaki','Page preview' => 'Pratonton halaman','Preview viewport' => 'Pratonton port paparan','Tablet' => 'Tablet','Desktop' => 'Komputer Riba','Preview width' => 'Lebar pratonton','Decrease width' => 'Kurangkan lebar','Preview width in pixels' => 'Lebar pratonton dalam piksel','Increase width' => 'Tingkatkan lebar','Preview as' => 'Pratonton sebagai','Guest' => 'Tetamu','Logged in' => 'Log masuk','Preview page' => 'Pratonton halaman','Expand preview for a closer look' => 'Kembangkan pratonton untuk melihat lebih dekat','Available with %s.' => 'Tersedia dengan %s.','Turn them on' => 'Hidupkannya','Optimizations for this page are turned off. %s to preview the page.' => 'Pengoptimuman untuk halaman ini dimatikan. %s untuk melihat pratonton halaman.','%s preview' => 'Pratonton %s','Isolated session · nothing is saved' => 'Sesi terpencil · tiada apa yang disimpan','Usage tracking' => 'Penjejakan penggunaan','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'Hantar laporan persekitaran tapak yang tidak sensitif untuk membantu Fluid Checkout meningkatkan keserasian. Laporan tidak dihantar sehingga diaktifkan dalam pilihan di bawah.','Send usage tracking reports to Fluid Checkout' => 'Hantar laporan penjejakan penggunaan ke Fluid Checkout','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'Laporan ini membantu kami meningkatkan keserasian dan sokongan untuk tapak anda dan dihantar setiap minggu apabila diaktifkan.','No customer, admin user, or any other sensitive data is included in the reports.' => 'Tiada pelanggan, pengguna pentadbir atau sebarang data sensitif lain disertakan dalam laporan.','Basic environment info' => 'Maklumat persekitaran asas','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'Data senarai WordPress, PHP, WooCommerce, tema dan pemalam. Sentiasa disertakan apabila pelaporan diaktifkan. Membantu kami memahami persekitaran yang digunakan oleh laman web anda.','Plugin settings' => 'Tetapan pemalam','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'Menghantar tetapan pemalam Fluid Checkout untuk membantu dengan permintaan sokongan dan membantu kami memahami cara anda menggunakan pemalam kami.','Coming soon' => 'Akan datang tidak lama lagi','Sales metrics' => 'Metrik jualan','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'Kiraan pesanan bulanan dan jumlah jualan selama setahun sebelum memasang Fluid Checkout sehingga hari ini. Membantu kami memahami sama ada anda menjana lebih banyak wang dengan pemasangan pemalam kami. Tiada data pelanggan atau pengguna akan dihantar.','Utilities' => 'Utiliti','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => 'Gunakan komponen lungsur turun <code>TomSelect</code> dan bukannya <code>select2</code>','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect ialah komponen pilihan juntai bawah yang lebih mudah yang kurang terdedah kepada ralat berbanding Select2, sambil menawarkan fungsi yang sama.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'Menetapkan saiz fon di dalam medan borang kepada 16px pada halaman yang dioptimumkan oleh pemalam ini untuk mengelakkan zum masuk secara automatik apabila berinteraksi dengan medan borang pada peranti kecil.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'Safari dan pelayar lain mungkin akan mengezum masuk secara automatik pada peranti mudah alih untuk memudahkan teks dibaca apabila saiz fon lebih kecil daripada 16px.','Enable script processing tracking on the browser console.' => 'Dayakan penjejakan pemprosesan skrip pada konsol pelayar.','Unminified assets' => 'Aset tidak diminimumkan','Google Maps scripts' => 'Skrip Peta Google','Do not remove duplicate Google Maps scripts' => 'Jangan alih keluar skrip Peta Google yang digandakan','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'Apabila diaktifkan, skrip Google Maps yang digandakan TIDAK AKAN dialih keluar yang boleh menyebabkan ralat dan masalah prestasi. Hanya gunakan pilihan ini semasa menyelesaikan masalah.','Widget areas' => 'Kawasan widget','Last step on mobile' => 'Langkah terakhir pada mudah alih','Display widgets only at last step on mobile' => 'Paparkan widget hanya pada langkah terakhir pada mudah alih','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'Paparkan widget lencana kepercayaan pembayaran hanya apabila melihat langkah pembayaran terakhir pada peranti mudah alih','Standard' => 'Piawai','VAT number field' => 'Medan nombor VAT','Add a VAT number field to the billing form.' => 'Tambahkan medan nombor VAT pada borang pengebilan.','Field label' => 'Label medan','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'Tetapkan label medan nombor VAT (iaitu nombor VAT). Di laman web berbilang bahasa, adalah lebih baik untuk membiarkan medan ini kosong dan menterjemahkan rentetan asal.','VAT Number' => 'Nombor VAT','EU-VAT' => 'EU-VAT','Enable the VAT number field to see more options' => 'Dayakan medan nombor VAT untuk melihat lebih banyak pilihan','VAT validation' => 'Pengesahan VAT','Validate VAT number field for EU-VAT during checkout' => 'Sahkan medan nombor VAT untuk EU-VAT semasa pembayaran','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'Memeriksa sama ada Nombor VAT yang diberikan adalah nombor VAT yang sah yang didaftarkan pada Pangkalan Data VIES Eropah (Sistem Pertukaran Maklumat VAT).','Shop VAT number' => 'Nombor VAT kedai','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'Nombor VAT kedai yang digunakan untuk meminta pengesahan EU-VAT dan dicetak pada invois.<br> <strong>Kami sangat mengesyorkan menambah nombor VAT Kedai anda</strong> kerana jika tidak, keputusan rundingan VIES mungkin tidak sah untuk tujuan perakaunan.<br> Iaitu: <code>ATU99999999</code> atau <code>EE999999999</code> .','Reverse charge' => 'Caj terbalik','Apply reverse charge mechanism' => 'Gunakan mekanisme cas songsang','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'Tetapkan kadar cukai kepada sifar dan paparkan &quot;Caj terbalik&quot; pada invois apabila nombor VAT pelanggan sah. Teks &quot;Caj terbalik&quot; yang berbeza mungkin diperlukan bergantung pada negara kedai.','Same country' => 'Negara yang sama','Apply reverse charge mechanism for transactions in the shop country:' => 'Gunakan mekanisme caj terbalik untuk transaksi di negara kedai:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'Membolehkan penggunaan mekanisme caj terbalik untuk transaksi antara syarikat di negara yang sama dengan kedai.','Reverse charge exceptions' => 'Pengecualian caj terbalik','Select additional countries to skip applying the reverse charge mechanism.' => 'Pilih negara tambahan untuk melangkau penggunaan mekanisme cas terbalik.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'Cukai akan dikenakan ke atas pesanan dari negara-negara ini walaupun nombor VAT yang sah diberikan.','Reverse charge label on invoices' => 'Label caj terbalik pada invois','Set the label of "reverse charge" on the checkout page and order details.' => 'Tetapkan label &quot;caj balik&quot; pada halaman pembayaran dan butiran pesanan.','Reverse charge text on invoices' => 'Teks caj terbalik pada invois','Set the label of "reverse charge" text on invoices.' => 'Tetapkan label teks &quot;caj terbalik&quot; pada invois.','Tax to be paid on reverse charge basis' => 'Cukai perlu dibayar atas dasar caj terbalik','Company name' => 'Nama syarikat','Autocomplete company name from VAT number' => 'Autolengkapkan nama syarikat daripada nombor VAT','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'Isi nama syarikat pengebilan berdasarkan nombor VAT yang sah yang diberikan oleh pelanggan.','Company name editing' => 'Pengeditan nama syarikat','Allow editing of auto-filled company name' => 'Benarkan pengeditan nama syarikat yang diisi secara automatik','When enabled, customers can change the company name associated with the provided VAT number.' => 'Apabila diaktifkan, pelanggan boleh menukar nama syarikat yang dikaitkan dengan nombor VAT yang diberikan.','EU-VAT for digital goods' => 'EU-VAT untuk barangan digital','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => 'Mulai 1 Januari 2015, pengubahsuaian telah dibuat pada peraturan VAT EU mengenai barangan digital, yang memberi kesan eksklusif kepada transaksi B2C. VAT ke atas barangan digital mesti dikira berdasarkan lokasi pelanggan dan bukti mengenainya perlu dikumpulkan (alamat IP dan alamat pengebilan).','Tax classes for digital goods' => 'Kelas cukai untuk barangan digital','Select some tax classes' => 'Pilih beberapa kelas cukai','Location evidence' => 'Bukti lokasi','Collect customer\'s location evidence' => 'Kumpul bukti lokasi pelanggan','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'Menyimpan alamat IP dan mengesahkannya dengan alamat pengebilan pelanggan. Pelanggan mesti mengesahkan alamat pengebilan mereka dengan menanda kotak pilihan pada halaman pembayaran jika negara daripada alamat pengebilan dan IP mereka tidak sepadan.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'Pilihan ini diuruskan dalam Fluid Checkout. <a href="%s">Tukarkannya dalam tetapan Akaun pelanggan</a> .','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'Pilihan ini diuruskan dalam Fluid Checkout. Tukarkannya di bawah Fluid Checkout &gt; Akaun pelanggan.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'Pilihan ini diuruskan dalam Fluid Checkout. Destinasi penghantaran sentiasa ditetapkan kepada &quot;Lalai kepada alamat penghantaran pelanggan&quot; apabila Fluid Checkout diaktifkan. Pelanggan masih boleh memberikan alamat penghantaran dan pengebilan yang berbeza semasa pembayaran.<br><br> Pilihan untuk menetapkan alamat pengebilan lalai agar sama dengan alamat penghantaran tersedia dalam <a href="%s">tetapan Fluid Checkout</a> .','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'Pilihan ini diuruskan dalam Fluid Checkout. Destinasi penghantaran sentiasa ditetapkan kepada &quot;Lalai kepada alamat penghantaran pelanggan&quot; apabila Fluid Checkout diaktifkan. Pelanggan masih boleh memberikan alamat penghantaran dan pengebilan yang berbeza semasa pembayaran.<br><br> Pilihan untuk menetapkan alamat pengebilan lalai agar sama dengan alamat penghantaran tersedia di WooCommerce &gt; Tetapan &gt; Pembayaran Cecair.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'Tetapan ini telah dipindahkan ke WP Admin &gt; Fluid Checkout &gt; Settings.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'Tab Tetapan WooCommerce ini tidak lagi digunakan dan akan dialih keluar dalam Fluid Checkout 6.0.','Go to settings page' => 'Pergi ke halaman tetapan','Hide this tab permanently' => 'Sembunyikan tab ini secara kekal','Site report preview' => 'Pratonton laporan tapak','This is the data that would be included in the next site environment report based on your current settings.' => 'Ini adalah data yang akan dimasukkan dalam laporan persekitaran tapak seterusnya berdasarkan tetapan semasa anda.','Loading report preview...' => 'Memuatkan pratonton laporan...','Could not load the site report preview. Try again.' => 'Tidak dapat memuatkan pratonton laporan tapak. Cuba lagi.','Could not send the site report. Try again.' => 'Tidak dapat menghantar laporan tapak. Cuba lagi.','Site report sent successfully.' => 'Laporan tapak berjaya dihantar.','Enable and send now' => 'Dayakan dan hantar sekarang','Close' => 'Tutup','A site report request is already in progress. Try again in a moment.' => 'Permintaan laporan tapak sedang dijalankan. Cuba lagi sebentar lagi.','Site environment reporting is disabled.' => 'Pelaporan persekitaran tapak telah dinyahdayakan.','No site report data is available to send.' => 'Tiada data laporan tapak tersedia untuk dihantar.','This site domain cannot send environment reports (local or development domains are excluded).' => 'Domain tapak ini tidak boleh menghantar laporan persekitaran (domain tempatan atau pembangunan dikecualikan).','A site report was sent recently. Try again later.' => 'Laporan tapak telah dihantar baru-baru ini. Cuba lagi nanti.','The site report could not be sent. Try again later.' => 'Laporan tapak tidak dapat dihantar. Cuba lagi nanti.','Site environment reporting is not available.' => 'Pelaporan persekitaran tapak tidak tersedia.','No site report data is available for the selected settings.' => 'Tiada data laporan tapak tersedia untuk tetapan yang dipilih.','You are not allowed to manage site reports.' => 'Anda tidak dibenarkan untuk mengurus laporan tapak.','PRO feature' => 'Ciri PRO','Other plugins' => 'Plugin lain','Get only this add-on &mdash; %s' => 'Dapatkan hanya alat tambah ini — %s','Install add-on' => 'Pasang alat tambah','Upgrade to PRO &mdash; %s' => 'Naik taraf kepada PRO — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => '<a target="_blank" href="%1$s">Dapatkan %2$s</a> untuk membuka kunci pilihan ini.','Add-on' => 'Tambahan','View documentation' => 'Lihat dokumentasi','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'Permintaan memerlukan pengguna WordPress yang telah log masuk. Abaikan user_id untuk menggunakan data pengguna semasa atau berikan user_id untuk menyasarkan akaun lain apabila pemanggil boleh mengedit pengguna tersebut (keupayaan edit_user). Permintaan yang tidak disahkan mengembalikan fc_api_forbidden. User_id yang tidak sah mengembalikan fc_api_user_not_found.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 dengan { &quot;data&quot;: { ... } } apabila pengendali mengembalikan muatan.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200 dengan { &quot;success&quot;: true } apabila tiada muatan (contohnya DELETE).','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'Kegagalan mengembalikan ralat REST WordPress JSON daripada WP_Error (kod, mesej, data.status). Kod wayar menggunakan awalan fc_api_*.','Forbidden access.' => 'Akses terlarang.','Target user was not found.' => 'Pengguna sasaran tidak ditemui.','This feature is not available.' => 'Ciri ini tidak tersedia.','A required address field is missing.' => 'Medan alamat yang diperlukan tiada.','Postcode or ZIP is invalid.' => 'Poskod atau ZIP tidak sah.','Phone number is invalid.' => 'Nombor telefon tidak sah.','State or county is invalid.' => 'Negeri atau daerah tidak sah.','Country is invalid or has no address fields.' => 'Negara tidak sah atau tiada medan alamat.','The request could not be processed.' => 'Permintaan itu tidak dapat diproses.','Back to previous step' => 'Kembali ke langkah sebelumnya','Skip to settings' => 'Langkau ke tetapan','Start over and return to the first guided setup step' => 'Mula semula dan kembali ke langkah persediaan berpanduan pertama','Start over' => 'Mula semula','Please complete all sub-steps before continuing.' => 'Sila lengkapkan semua sub-langkah sebelum meneruskan.','Expand' => 'Kembangkan','Collapse' => 'Lipat','Skip' => 'Langkau','Mark as complete' => 'Tandakan sebagai selesai','Mark as incomplete' => 'Tandakan sebagai tidak lengkap','View full-size image: %s' => 'Lihat imej bersaiz penuh: %s','Full-size setup guide image' => 'Imej panduan persediaan bersaiz penuh','Close image' => 'Tutup imej','Fluid Checkout Guided Setup' => 'Persediaan Berpandu Pemeriksaan Cecair','Welcome' => 'Selamat datang','Explore your checkout' => 'Terokai pembayaran anda','All set' => 'Semua sedia','You do not have permission to access this page.' => 'Anda tidak mempunyai kebenaran untuk mengakses halaman ini.','Go to step %1$d: %2$s' => 'Pergi ke langkah %1$d: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'Persediaan berpanduan ini membantu anda membiasakan diri dengan Fluid Checkout. Langkah-langkah di bawah hanyalah ruang letak buat masa ini.','Continue to the next step when you are ready.' => 'Teruskan ke langkah seterusnya apabila anda sudah bersedia.','Open your store checkout to see Fluid Checkout in action.' => 'Buka pembayaran kedai anda untuk melihat Fluid Checkout sedang beraksi.','View checkout page' => 'Lihat halaman pembayaran','You can return to Fluid Checkout settings to continue configuring your store.' => 'Anda boleh kembali ke tetapan Fluid Checkout untuk terus mengkonfigurasi kedai anda.','Review checkout and cart settings' => 'Semak tetapan pembayaran dan troli','Explore add-ons from the dashboard' => 'Terokai alat tambah daripada papan pemuka','Finish & go to settings' => 'Selesai &amp; pergi ke tetapan','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Kemas kini pilihan keterlihatan medan telefon pengebilan daripada nilai legasi agar sepadan dengan konvensyen WooCommerce.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Kemas kini pilihan keterlihatan medan telefon penghantaran daripada nilai legasi agar sepadan dengan konvensyen WooCommerce.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'Salin tetapan warna latar belakang ringkasan pesanan kepada pilihan warna latar belakang lajur sekunder Reka bentuk Split yang baharu.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'Ciri medan pilih yang dipertingkatkan sentiasa dinyahdayakan apabila menggunakan pemalam Biteship.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Kedudukan membuat pesanan sentiasa ditetapkan kepada &quot;Di bawah ringkasan pesanan&quot; apabila menggunakan German Market. Plugin tersebut memerlukan butang membuat pesanan dan kotak pilihan yang sah dipaparkan di bawah ringkasan pesanan.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Kedudukan pesanan sentiasa ditetapkan kepada &quot;Di bawah ringkasan pesanan&quot; apabila menggunakan Germanized untuk WooCommerce. Plugin tersebut memerlukan butang pesanan dan kotak pilihan sah dipaparkan di bawah ringkasan pesanan.','Edit pickup locations' => 'Edit lokasi pengambilan','Use local pickup label from WooCommerce settings' => 'Gunakan label pengambilan setempat daripada tetapan WooCommerce','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'Apabila diaktifkan, label pilihan pengambilan semasa pembayaran sepadan dengan tajuk daripada tetapan lokasi pengambilan WooCommerce. Apabila dinyahdayakan, label menggunakan teks &quot;Pengambilan tempatan&quot; yang boleh diterjemahkan daripada Fluid Checkout.','Button label for applying coupon codesApply' => 'Mohon','Checkout step titleContact' => 'Kenalan','Checkout step titleShipping' => 'Penghantaran','Checkout step titleBilling' => 'Pengebilan','Checkout step titlePayment' => 'Bayaran','Checkout substep change link labelChange' => 'Berubah','Checkout substep save link labelSave changes' => 'Simpan perubahan','Substep review textNone.' => 'tiada.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'Tiada imej dipilih.','Settings sectionCart' => 'Troli','Settings sectionOrder pay' => 'Pesanan bayar','Settings sectionThank you' => 'terima kasih','Settings section titleIntegrations' => 'Integrasi','Settings section titleLicense keys' => 'Kunci lesen','Captcha positionBefore place order section' => 'Sebelum bahagian pesanan tempat','Captcha positionBefore place order button' => 'butang sebelum tempat pesanan','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'tutup','Log in link label at checkout contact stepLog in' => 'Log masuk','Log in separator label at for when guest checkout is disabledOr continue below' => 'Atau teruskan di bawah','Log in separator label at for when guest checkout is disabledOr continue as a guest' => 'Atau teruskan sebagai tetamu','Clear image selection on admin pages.Remove image' => 'Alih keluar imej','shipping packagesShipping %d' => 'Penghantaran %d','shipping packagesShipping' => 'Penghantaran','Used as fallback for "Proceed to next step" button labelnext step' => 'langkah seterusnya','Substep review checkbox valueYes' => 'Ya','Substep review checkbox line%1$s: %2$s' => '%1$s: %2$s','Dummy customer first name in the admin previewJohn' => 'John','Dummy customer last name in the admin previewDoe' => 'Rusa betina','Dummy customer company in the admin previewExample Company' => 'Syarikat Contoh','Dummy customer street address in the admin preview123 Main Street' => '123 Jalan Utama','Dummy customer city in the admin previewAnytown' => 'Anytown','Dummy order notes in the admin previewPlease leave the package at the front door.' => 'Sila tinggalkan bungkusan itu di pintu hadapan.','Dummy product name in the admin previewBeanie' => 'Beanie','Dummy product name in the admin previewCap' => 'Topi','Dummy product name in the admin previewT-Shirt' => 'T-Shirt','Dummy order update in the admin previewWe received your order and will send you an update when it ships.' => 'Kami telah menerima pesanan anda dan akan menghantar kemas kini kepada anda apabila ia dihantar.','Dummy download in the admin previewUser guide' => 'Panduan pengguna','Google Places API versionsPlaces API (New)' => 'API Tempat (Baharu)','Google Places API versionsPlaces API (Legacy)' => 'API Tempat (Legasi)','Brasil API versionsVersion 1' => 'Versi 1','Brasil API versionsVersion 2' => 'Versi 2','Delayed account creation benefits placeholder text✔ Checkout faster next time
